package com.yeyamo_mobile.api.partner_service.infrastructure.messaging;
import java.time.Instant;import java.util.concurrent.TimeUnit;import org.springframework.beans.factory.annotation.Value;import org.springframework.kafka.core.KafkaTemplate;import org.springframework.scheduling.annotation.Scheduled;import org.springframework.stereotype.Component;import org.springframework.transaction.annotation.Transactional;
@Component public class PartnerOutboxPublisher{private final PartnerOutboxRepository repo;private final KafkaTemplate<String,String>kafka;private final String topic;public PartnerOutboxPublisher(PartnerOutboxRepository r,KafkaTemplate<String,String>k,@Value("${yeyamo.kafka.topics.partner-events:partner-events}")String t){repo=r;kafka=k;topic=t;}@Scheduled(fixedDelayString="${yeyamo.outbox.publish-delay-ms:1000}")@Transactional public void publish(){for(PartnerOutboxEvent e:repo.findTop100ByPublishedAtIsNullOrderByOccurredAtAsc())try{kafka.send(topic,e.getAggregateId().toString(),e.getPayload()).get(5,TimeUnit.SECONDS);e.setPublishedAt(Instant.now());e.setLastError(null);repo.save(e);}catch(Exception x){e.setAttempts(e.getAttempts()+1);String m=x.getMessage();e.setLastError(m==null?"Kafka error":m.substring(0,Math.min(1000,m.length())));repo.save(e);}}}
